window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[80]={"id":"080","numero":80,"titre":"Dopage et conduites dopantes","objectifs":[{"id":"80-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition du dopage et des conduites dopantes","contenu":"<div class=\"notion-course\"><h4>Conduite dopante et violation antidopage</h4><p>Une conduite dopante vise à améliorer une performance ou à <span class=\"nc-green nc-bold\">affronter un obstacle</span> par l’usage de produits ou <span class=\"nc-pink nc-bold\">méthodes</span>, dans le sport, les études, le travail ou les activités artistiques. Le dopage sportif relève d’un cadre réglementaire spécifique.</p><ul><li>Le dopage réglementaire ne se limite pas à un test positif ou à une prise le jour de la compétition : usage, possession, trafic, administration, falsification ou refus de contrôle peuvent relever de violations.</li><li>Certaines interdictions valent en permanence, y compris à l’entraînement.</li><li>Distinguer efficacité recherchée, risques médicaux et statut réglementaire ; une substance autorisée n’est pas nécessairement sans danger.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.afld.fr/espace-des-professionnels-de-sante/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Espace des professionnels de santé</a></li><li><a href=\"https://www.wada-ama.org/fr/liste-des-interdictions\" target=\"_blank\" rel=\"noopener noreferrer\">AMA · Liste des substances et méthodes interdites</a></li></ul><p></p></details><details data-lisa-review=\"20261014\"><summary>Situations de départ LiSA vérifiées</summary><p>Attendus consultés sur LiSA 2026 le 14 octobre 2026, reformulés pour la révision.</p><ul><li><a href=\"https://livret.uness.fr/lisa/2026/%C3%89valuation_de_l%27aptitude_au_sport_et_r%C3%A9daction_d%27un_certificat_de_non_contre-indication_SDD-335\" target=\"_blank\" rel=\"noopener noreferrer\">SDD 335 · Évaluation de l’aptitude au sport et certificat de non contre-indication</a><ul><li>Explorer pratique sportive, âge et terrain ; adapter examen et explorations et repérer surentraînement ou addiction au sport.</li><li>Prévenir les conduites dopantes et identifier les situations nécessitant questionnaire ou certificat médical.</li></ul></li></ul><p>Les liens ciblent les compétences pertinentes pour cet item ; ils ne signifient pas que la fiche couvre à elle seule toute la situation de départ.</p></details>","frequence":0},{"id":"80-2","rang":"A","rubrique":"Définition","titre":"Savoir comment un produit est qualifié de dopant, comment une méthode est qualifiée de dopante","contenu":"<div class=\"notion-course\"><h4>Lire la liste applicable</h4><ul><li>La liste de l’AMA précise les <span class=\"nc-pink nc-bold\">substances</span>, <span class=\"nc-pink nc-bold\">méthodes</span>, périodes, sports, voies d’administration, seuils et exceptions.</li><li>Vérifier le millésime en vigueur à la date d’utilisation : la publication de la liste de l’année suivante ne la rend pas immédiatement applicable.</li><li>Grandes classes : S0–S5 et <span class=\"nc-pink nc-bold\">méthodes</span> interdites en permanence ; S6–S9 en compétition ; P1 selon le sport, avec particularités.</li><li>Une AUT peut permettre un usage médical justifié selon les conditions prévues ; une ordonnance seule ne remplace pas cette autorisation.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.wada-ama.org/fr/liste-des-interdictions\" target=\"_blank\" rel=\"noopener noreferrer\">AMA · Liste des substances et méthodes interdites</a></li><li><a href=\"https://www.afld.fr/la-lutte-antidopage/education-et-prevention/aut/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Demande d’autorisation d’usage à des fins thérapeutiques</a></li></ul><p></p></details>","frequence":0},{"id":"80-3","rang":"B","rubrique":"Définition","titre":"Connaître les principales substances et méthodes dopantes","contenu":"<div class=\"notion-course\"><h4>Principales classes — exemples à vérifier sur la liste en vigueur</h4><table><thead><tr><th>Classe</th><th>Exemples / vigilance</th></tr></thead><tbody><tr><td>S0 · Non approuvées</td><td>Produits non autorisés en thérapeutique humaine et entrant dans cette catégorie.</td></tr><tr><td>S1 · Anabolisants</td><td>Stéroïdes androgènes et autres <span class=\"nc-pink nc-bold\">agents anabolisants</span>.</td></tr><tr><td>S2 · Hormones et facteurs de croissance</td><td>EPO, hormone de croissance et agents apparentés.</td></tr><tr><td>S3 · Bêta-2 agonistes</td><td>Exceptions limitées à certaines molécules inhalées et doses : ne pas généraliser à toute la classe.</td></tr><tr><td>S4 · Modulateurs hormonaux et métaboliques</td><td>Anti-aromatases, modulateurs des récepteurs œstrogéniques et agents métaboliques.</td></tr><tr><td>S5 · Diurétiques et agents masquants</td><td>Risques de déshydratation et troubles ioniques.</td></tr><tr><td>S6 · Stimulants</td><td><span class=\"nc-purple_bg\">Amphétamines</span>, <span class=\"nc-purple_bg\">cocaïne</span>, <span class=\"nc-purple_bg\">méthylphénidate</span>, <span class=\"nc-purple_bg\">modafinil</span>.</td></tr><tr><td>S7 · Narcotiques</td><td>Notamment morphine, méthadone, buprénorphine et tramadol.</td></tr><tr><td>S8 · Cannabinoïdes</td><td>Cannabinoïdes interdits en compétition, sauf cannabidiol ; attention à la contamination des produits au CBD.</td></tr><tr><td>S9 · Glucocorticoïdes</td><td>Voies systémiques concernées, notamment toute voie injectable, orale et rectale ; vérifier délai d’élimination et voie.</td></tr><tr><td>P1 · Bêtabloquants</td><td>Dans certains sports ; périmètre et périodes à vérifier.</td></tr></tbody></table><h4><span class=\"nc-pink nc-bold\">Méthodes</span></h4><ul><li>Manipulations du sang ou de ses composants.</li><li>Manipulations chimiques/physiques des contrôles et certaines perfusions ou injections IV selon volume et contexte.</li><li>Dopage génétique et cellulaire.</li></ul><div class=\"callout\"><p>La caféine n’est pas une substance interdite par principe. Ne pas confondre programme de surveillance et liste d’interdiction. La conformité dépend de la substance exacte et des conditions d’usage.</p></div></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.wada-ama.org/fr/liste-des-interdictions\" target=\"_blank\" rel=\"noopener noreferrer\">AMA · Liste des substances et méthodes interdites</a></li><li><a href=\"https://medicaments.afld.fr/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Vérifier un médicament</a></li></ul><p></p></details>","frequence":1},{"id":"80-4","rang":"B","rubrique":"Définition","titre":"Connaître l’existence des diverses formes de dopage","contenu":"<div class=\"notion-course\"><h4>Des formes multiples</h4><ul><li>Produits : médicaments détournés, <span class=\"nc-pink nc-bold\">substances</span> illicites, hormones, compléments contaminés ou produits expérimentaux.</li><li><span class=\"nc-pink nc-bold\">Méthodes</span> : sanguines, chimiques/physiques, génétiques ou cellulaires.</li><li>Usage isolé ou associations, recherche de force/endurance, contrôle du poids, attention ou récupération.</li><li>Les conduites dopantes dépassent le sport de haut niveau ; rechercher le contexte, la pression de performance, le circuit d’approvisionnement et une addiction associée.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li></ul><p></p></details>","frequence":0},{"id":"80-5","rang":"B","rubrique":"Epidémiologie","titre":"Connaître la prévalence générale","contenu":"<div class=\"notion-course\"><h4>Ne pas confondre fréquence réelle et résultats de contrôle</h4><p>La prévalence réelle est difficile à mesurer : sous-déclaration, populations hétérogènes, contrôles ciblés et <span class=\"nc-pink nc-bold\">substances</span> non détectées. Le pourcentage de résultats analytiques anormaux dépend de l’année, du sport, des tests et de la population contrôlée.</p><ul><li>Un résultat analytique anormal n’est pas automatiquement une violation définitivement établie.</li><li>Le chiffre de 5–10 % présent dans la fiche précédente ne doit pas être présenté comme une prévalence générale actuelle sans enquête précise.</li><li>Comparer seulement des données avec même définition et dénominateur ; retenir que dopage détecté et conduites réelles diffèrent.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.afld.fr/espace-des-professionnels-de-sante/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Espace des professionnels de santé</a></li></ul><p></p></details>","frequence":0},{"id":"80-6","rang":"B","rubrique":"Définition","titre":"Connaître les principes, règles, méthodes, et organisations de la lutte contre le dopage","contenu":"<div class=\"notion-course\"><h4>Acteurs et <span class=\"nc-pink nc-bold\">méthodes</span></h4><table><thead><tr><th>Acteur / outil</th><th>Rôle</th></tr></thead><tbody><tr><td>AMA</td><td>Code mondial, standards, liste et coordination internationale.</td></tr><tr><td><span class=\"nc-yellow_bg\">AFLD</span></td><td>Organisation nationale : contrôles, prévention, éducation et missions prévues par le droit français.</td></tr><tr><td>Fédérations / organisations compétentes</td><td>Règles, contrôles et gestion des résultats selon leurs compétences.</td></tr><tr><td>AMPD</td><td>Prévention, consultations et accompagnement médical.</td></tr><tr><td>Contrôles</td><td>Prélèvements et analyses en ou hors compétition.</td></tr><tr><td>Passeport biologique</td><td>Suivi longitudinal : modules hématologique, stéroïdien et endocrinien ; le module endocrinien n’est plus seulement un projet.</td></tr></tbody></table><ul><li>La détection directe recherche des <span class=\"nc-pink nc-bold\">substances</span>/métabolites ; l’approche longitudinale recherche des variations compatibles avec un dopage.</li><li>Aucune méthode ne détecte toutes les pratiques.</li><li>Séparer prise en charge médicale, contrôle et sanction ; respecter droits et procédures.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.afld.fr/espace-des-professionnels-de-sante/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Espace des professionnels de santé</a></li><li><a href=\"https://www.wada-ama.org/sites/default/files/2023-07/2023_laboratory_guidelines_endocrine_module_final_v1_0.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">AMA · Module endocrinien du passeport biologique</a></li></ul><p></p></details>","frequence":0},{"id":"80-7","rang":"B","rubrique":"Définition","titre":"Savoir à qui s’applique la règlementation anti-dopage","contenu":"<div class=\"notion-course\"><h4>Sportifs et entourage</h4><ul><li>Les règles s’appliquent selon le Code du sport et les règlements antidopage, aux sportifs concernés, amateurs comme professionnels ; elles ne se limitent pas aux titulaires d’une licence.</li><li>Des obligations concernent aussi l’encadrement et les professionnels qui administrent, fournissent ou facilitent des pratiques interdites.</li><li>Contrôles possibles en et hors compétition dans le cadre applicable.</li><li>Refus, soustraction ou falsification peuvent constituer une violation distincte ; ne pas annoncer une sanction automatiquement identique dans tous les cas.</li><li>Le sportif est responsable des <span class=\"nc-pink nc-bold\">substances</span> présentes dans son organisme ; vérifier prescriptions, automédication et compléments.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.afld.fr/espace-des-professionnels-de-sante/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Espace des professionnels de santé</a></li><li><a href=\"https://www.sports.gouv.fr/le-medecin-face-au-dopage-2730\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère des Sports · Le médecin face au dopage</a></li></ul><p></p></details>","frequence":0},{"id":"80-8","rang":"A","rubrique":"Prise en charge","titre":"Savoir rechercher le caractère dopant ou non d’une prescription médicale","contenu":"<div class=\"notion-course\"><h4>Prescription chez un sportif</h4><ol><li>Identifier sport, niveau, calendrier, traitement exact, voie et dose.</li><li>Vérifier le médicament dans le moteur AFLD puis la liste applicable ; en cas de doute, solliciter l’organisme compétent.</li><li>Rechercher une alternative autorisée médicalement adaptée.</li><li>Si traitement interdit nécessaire : documenter le diagnostic et vérifier la procédure d’AUT selon niveau et urgence.</li><li>Ne pas retarder un traitement urgent ; une demande rétroactive est possible dans certaines situations encadrées.</li><li>Informer et tracer la décision. Une ordonnance ne garantit pas l’absence de sanction sans AUT lorsqu’elle est requise.</li></ol></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://medicaments.afld.fr/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Vérifier un médicament</a></li><li><a href=\"https://www.afld.fr/la-lutte-antidopage/education-et-prevention/aut/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Demande d’autorisation d’usage à des fins thérapeutiques</a></li></ul><p></p></details>","frequence":0},{"id":"80-9","rang":"B","rubrique":"Suivi et/ou pronostic","titre":"Connaître les risques liés au dopage et aux conduites dopantes","contenu":"<div class=\"notion-course\"><h4>Complications médicales à rechercher</h4><table><thead><tr><th>Produits / pratiques</th><th>Risques possibles</th></tr></thead><tbody><tr><td>Stéroïdes anabolisants</td><td>Troubles cardiovasculaires, hépatiques, endocriniens/fertilité, acné et <span class=\"nc-blue_bg\">manifestations</span> psychiatriques.</td></tr><tr><td>EPO / manipulations sanguines</td><td>Hyperviscosité et thromboses ; risques infectieux et transfusionnels selon pratique.</td></tr><tr><td>Stimulants</td><td>Tachycardie, HTA, arythmie, hyperthermie, convulsions, agitation et psychose.</td></tr><tr><td>Diurétiques</td><td>Déshydratation, troubles hydroélectrolytiques, atteinte rénale et rythme cardiaque.</td></tr><tr><td>Hormones / insuline</td><td>Déséquilibres métaboliques, notamment hypoglycémie sévère avec l’insuline.</td></tr><tr><td>Injections / associations</td><td>Infections, surdosages, interactions et dépendance.</td></tr></tbody></table><p>Rechercher une urgence devant <span class=\"nc-green_bg\">douleur</span> thoracique, dyspnée, trouble de conscience, hyperthermie ou signes neurologiques. Le bilan dépend du produit et du contexte.</p><h4>Conséquences réglementaires</h4><p><span class=\"nc-red nc-bold\">Sanctions disciplinaires</span> possibles, et pénales pour certaines infractions. Leur nature dépend de la violation et des circonstances ; ni un résultat positif ni une suspicion ne suffisent à annoncer une durée universelle.</p></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.sports.gouv.fr/media/8943/download\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère des Sports · Substances et risques du dopage</a></li><li><a href=\"https://www.afld.fr/espace-des-professionnels-de-sante/\" target=\"_blank\" rel=\"noopener noreferrer\">AFLD · Espace des professionnels de santé</a></li></ul><p></p></details>","frequence":0},{"id":"80-10","rang":"B","rubrique":"Prise en charge","titre":"Connaître les grands principes de la politique de prévention du dopage","contenu":"<div class=\"notion-course\"><h4>Prévention et rôle du médecin</h4><ul><li>Informer sur les risques, vérifier médicaments et compléments, explorer les pressions de performance et proposer des alternatives sûres.</li><li><span class=\"nc-yellow_bg\">AMPD</span> : consultation, prévention, recherche et orientation ; coordination avec médecine du sport et addictologie.</li><li>Face à des signes évoquant un dopage : appliquer les obligations du Code du sport, notamment refuser le certificat sportif concerné, informer, proposer les soins et transmettre les constatations au médecin responsable de l’<span class=\"nc-yellow_bg\">AMPD</span> en informant le patient.</li><li>Ne pas confondre cette procédure médicale avec une dénonciation nominative automatique à une fédération. Respecter les modalités légales et le secret professionnel.</li><li>Prévenir chez sportifs, encadrants et autres publics exposés aux conduites dopantes ; accompagner sans jugement et sans banalisation.</li></ul></div><details><summary>Sources et compléments</summary><p>Relecture du 14 octobre 2026. Couleurs reprises des passages correspondants de ton cours Notion.</p><ul><li><a href=\"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204\" target=\"_blank\" rel=\"noopener noreferrer\">Ton cours Notion · Dopage et conduites dopantes (80)</a></li><li><a href=\"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf\" target=\"_blank\" rel=\"noopener noreferrer\">CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024)</a></li><li><a href=\"https://www.sports.gouv.fr/le-medecin-face-au-dopage-2730\" target=\"_blank\" rel=\"noopener noreferrer\">Ministère des Sports · Le médecin face au dopage</a></li></ul><p></p></details>","frequence":0}],"astuces":[{"type":"piege","titre":"Ordonnance","contenu":"<div class=\"notion-course\"><p>Prescription médicale ≠ AUT.</p></div>"},{"type":"piege","titre":"Calendrier","contenu":"<div class=\"notion-course\"><p>Vérifier le millésime en vigueur, la voie, la dose et la période.</p></div>"}],"strategie":{"Démarche diagnostique":"<div class=\"notion-course\"><ul><li>Identifier produits, <span class=\"nc-pink nc-bold\">méthodes</span>, contexte et urgences.</li></ul></div>","Prise en charge":"<div class=\"notion-course\"><ul><li>Soigner et orienter AMPD ; vérifier AFLD/AUT et tracer l’information.</li></ul></div>"},"liensGlobaux":[{"href":"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204","label":"Ton cours Notion ↗"},{"href":"https://www.asso-aesp.fr/wp-content/uploads/2024/04/EDN-Psychiatrie-et-addictologie-4ed-bd.pdf","label":"CNUP–AESP–CUNEA · Référentiel de psychiatrie et addictologie, 4e édition (2024) ↗"},{"href":"https://www.afld.fr/espace-des-professionnels-de-sante/","label":"AFLD · Espace des professionnels de santé ↗"},{"href":"https://www.wada-ama.org/fr/liste-des-interdictions","label":"AMA · Liste des substances et méthodes interdites ↗"},{"href":"https://www.afld.fr/la-lutte-antidopage/education-et-prevention/aut/","label":"AFLD · Demande d’autorisation d’usage à des fins thérapeutiques ↗"},{"href":"https://medicaments.afld.fr/","label":"AFLD · Vérifier un médicament ↗"},{"href":"https://www.wada-ama.org/sites/default/files/2023-07/2023_laboratory_guidelines_endocrine_module_final_v1_0.pdf","label":"AMA · Module endocrinien du passeport biologique ↗"},{"href":"https://www.sports.gouv.fr/le-medecin-face-au-dopage-2730","label":"Ministère des Sports · Le médecin face au dopage ↗"},{"href":"https://www.sports.gouv.fr/media/8943/download","label":"Ministère des Sports · Substances et risques du dopage ↗"}],"arbre":{"rootId":"entry","nodes":[{"id":"entry","kind":"decision","label":"Produit, méthode ou demande de performance ?","detail":"<ul><li>Entretien confidentiel : traitements, compléments, injections, objectifs et contexte sportif.</li><li>Distinguer conduite dopante et violation des règles antidopage.</li></ul>","branches":[{"label":"Symptômes graves / intoxication","to":"urgence"},{"label":"Vérification de prescription ou méthode","to":"verifier"}]},{"id":"urgence","kind":"urgent","label":"Traiter l’urgence et rechercher les produits associés","detail":"<ul><li>Risques cardiovasculaires, thrombotiques, endocriniens, psychiatriques et infectieux.</li></ul>","branches":[]},{"id":"verifier","kind":"decision","label":"Déterminer le cadre et la liste en vigueur à la date d’usage","detail":"<ul><li>Discipline, compétition/hors compétition, voie, dose et période d’élimination.</li><li>Consulter AMA/AFLD ; ne pas se fier à une liste ancienne ou à la seule ordonnance.</li></ul>","branches":[{"label":"Substance/méthode interdite dans ce cadre","to":"therapeutique"},{"label":"Non interdite dans ce cadre","to":"prevenir"},{"label":"Doute non résolu","to":"expert"}]},{"id":"expert","kind":"uncertain","label":"Demander un avis antidopage compétent","detail":"<ul><li>Vérifier spécialité, principes actifs et méthode ; tracer l’information.</li></ul>","branches":[]},{"id":"therapeutique","kind":"decision","label":"Besoin thérapeutique réel et alternative autorisée ?","detail":"<ul><li>Ne jamais refuser un soin urgent ; organiser l’évaluation d’une AUT selon conditions.</li><li>Une prescription ne vaut pas autorisation d’usage thérapeutique.</li></ul>","branches":[{"label":"Traitement nécessaire","to":"aut"},{"label":"Pas d’indication médicale","to":"prevenir"}]},{"id":"aut","kind":"finish","label":"Vérifier la procédure d’AUT compétente et les justificatifs","detail":"<ul><li>Anticiper lorsque possible ; règles particulières des demandes rétroactives.</li></ul>","branches":[]},{"id":"prevenir","kind":"finish","label":"Informer, soigner et orienter si besoin","detail":"<ul><li>« Non interdit » ne signifie pas sans risque ; compléments parfois contaminés.</li><li>Proposer une prise en charge et une AMPD selon situation ; respecter le secret et le cadre légal.</li></ul>","branches":[]}]},"cards":[{"i":"cc73afdb3dbb","n":80,"o":"80-1","u":"Définition","t":"Connaître la définition du dopage et des conduites dopantes","q":"Le dopage se limite-t-il à une prise en compétition ?","a":"<div class=\"notion-course\"><ul><li>Non : interdictions en permanence et autres violations possibles ; les conduites dopantes dépassent aussi le sport.</li></ul></div>"},{"i":"899fa3b8053a","n":80,"o":"80-2","u":"Définition","t":"Savoir comment un produit est qualifié de dopant, comment une méthode est qualifiée de dopante","q":"Quelle liste utiliser en octobre avant une compétition ?","a":"<div class=\"notion-course\"><ul><li>Le millésime actuellement en vigueur ; publication d’une liste future ≠ entrée en vigueur.</li></ul></div>"},{"i":"59c7da1082af","n":80,"o":"80-3","u":"Définition","t":"Connaître les principales substances et méthodes dopantes","q":"Le méthylphénidate peut-il poser un problème antidopage ?","a":"<div class=\"notion-course\"><ul><li>Oui : stimulant interdit en compétition ; vérifier prescription, situation et AUT requise.</li></ul></div>"},{"i":"5567f4198c6a","n":80,"o":"80-3","u":"Définition","t":"Connaître les principales substances et méthodes dopantes","q":"Un produit au CBD est-il garanti sans risque antidopage ?","a":"<div class=\"notion-course\"><ul><li>Non : le CBD est excepté, mais contamination par d’autres cannabinoïdes possible.</li></ul></div>"},{"i":"9d7b20831f24","n":80,"o":"80-4","u":"Définition","t":"Connaître l’existence des diverses formes de dopage","q":"Quelles grandes méthodes dopantes connaître ?","a":"<div class=\"notion-course\"><ul><li>Manipulations sanguines, chimiques/physiques, génétiques/cellulaires.</li></ul></div>"},{"i":"af9e8428dd59","n":80,"o":"80-5","u":"Epidémiologie","t":"Connaître la prévalence générale","q":"Un taux de tests positifs mesure-t-il la prévalence réelle ?","a":"<div class=\"notion-course\"><ul><li>Non : contrôles ciblés, sensibilité, définitions et population différente.</li></ul></div>"},{"i":"1ce627d53f05","n":80,"o":"80-6","u":"Définition","t":"Connaître les principes, règles, méthodes, et organisations de la lutte contre le dopage","q":"Quels modules du passeport biologique connaître ?","a":"<div class=\"notion-course\"><ul><li>Hématologique, stéroïdien et endocrinien.</li></ul></div>"},{"i":"c83abdc18536","n":80,"o":"80-7","u":"Définition","t":"Savoir à qui s’applique la règlementation anti-dopage","q":"Un sportif amateur échappe-t-il aux règles antidopage ?","a":"<div class=\"notion-course\"><ul><li>Non : le statut amateur ne constitue pas une exemption.</li></ul></div>"},{"i":"4012698956ef","n":80,"o":"80-8","u":"Prise en charge","t":"Savoir rechercher le caractère dopant ou non d’une prescription médicale","q":"Une ordonnance suffit-elle à autoriser une substance interdite ?","a":"<div class=\"notion-course\"><ul><li>Non : une AUT peut être nécessaire ; vérifier conditions et organisme compétent.</li></ul></div>"},{"i":"844d2d130ac4","n":80,"o":"80-9","u":"Suivi et/ou pronostic","t":"Connaître les risques liés au dopage et aux conduites dopantes","q":"Quel danger majeur d’un stimulant associé à hyperthermie et tachycardie ?","a":"<div class=\"notion-course\"><ul><li>Complication aiguë potentiellement grave : urgence, surveillance et traitement adapté.</li></ul></div>"},{"i":"c19ff0635b97","n":80,"o":"80-10","u":"Prise en charge","t":"Connaître les grands principes de la politique de prévention du dopage","q":"Vers quelle structure médicale orienter une personne ayant des pratiques dopantes ?","a":"<div class=\"notion-course\"><ul><li>Une antenne médicale de prévention du dopage, avec soins adaptés et application des obligations légales.</li></ul></div>"}],"courseEdition":{"source":"notion","notionUrl":"https://app.notion.com/p/2ad37f85d9418112ac16c41670d4a1c9?pvs=204","reviewedAt":"2026-10-14","note":"Cours, cartes et arbres relus. Couleurs des passages Notion correspondants ; références et compléments identifiés dans chaque objectif.","sddStatus":"Situations LiSA vérifiées le 14 octobre 2026 dans la session UNESS connectée.","algorithms":1,"lisaSituations":[{"number":335,"title":"Évaluation de l’aptitude au sport et certificat de non contre-indication","url":"https://livret.uness.fr/lisa/2026/%C3%89valuation_de_l%27aptitude_au_sport_et_r%C3%A9daction_d%27un_certificat_de_non_contre-indication_SDD-335","expectations":["Explorer pratique sportive, âge et terrain ; adapter examen et explorations et repérer surentraînement ou addiction au sport.","Prévenir les conduites dopantes et identifier les situations nécessitant questionnaire ou certificat médical."],"verifiedAt":"2026-10-14"}]}};
